-- 2023/week-one-preview.mdx
INSERT INTO articles (id, season_year, week_number, kind, slug, title, summary, intro_markdown, outro_markdown, status, published_at, author_id, author_slug)
VALUES ('82a261cf-cca7-4d69-a333-f6776f06bf0f', 2023, 1, 'preview', '2023/week-one-preview', 'Week 1 Preview', 'In Week 1, the two-time defending champions Cookin'' It Up face off against the Disney Pixar Baddies, while other matchups include Team ETERNAL PAIN against Chubbin N’ Grubbin, Team Drako against Drake and Travis, Great Waller China against Olave Garden, Code Monkey against Meet the Stevensons, and YoungBoys Lover against the Los Angeles Akers, with a highly anticipated rivalry game between Code Monkey and Meet the Stevensons as the highlight.', NULL, '> **_NOTE:_**  Matchup of the week and the headliner matchup will have a post game press conference', 'published', '2023-09-07', NULL, NULL)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO article_matchups (id, article_id, position, slot_label, away_team_name, home_team_name, away_record, home_record, line, away_score, home_score, body)
VALUES
  ('b887460d-4ade-4b1e-a157-db09fa91a804', '82a261cf-cca7-4d69-a333-f6776f06bf0f', 1, 'TNF Opening night (NBC/ Peacock)', 'Cookin’ It Up', 'Disney Pixar Baddies', NULL, NULL, 'Baddies -2.6', NULL, NULL, 'The two time defending champions will look to start the season off with a positive note as they take on the Disney Pixar Baddies. The Baddies want to make a statement opening weekend and show they’re not to be fooled around with.'),
  ('76083e87-3516-4a2e-afdb-f79612c7cf2b', '82a261cf-cca7-4d69-a333-f6776f06bf0f', 2, '1:00 (FOX)', 'Team ETERNAL PAIN', 'Chubbin N’ Grubbin', NULL, NULL, 'PAIN -3.9', NULL, NULL, 'These two teams have been on the opposite ends of the table these last couple years but both owners continue to have high expectations going into the new year.'),
  ('19af1e53-d283-4c7d-9231-381df200a95e', '82a261cf-cca7-4d69-a333-f6776f06bf0f', 3, '1:00 (CBS)', 'Team Drako', 'Drake and Travis', NULL, NULL, 'Travis -5.2', NULL, NULL, 'A matchup with similar names and similar situations as both teams might be missing their first round pick week 1. D&T will be favored going into this matchup but Team Drako will want to prove otherwise.'),
  ('2e6d58d0-547f-4348-8cd5-9fa2f33a2981', '82a261cf-cca7-4d69-a333-f6776f06bf0f', 4, '4:25 (Fox)', 'Great Waller China', 'Olave Garden', NULL, NULL, 'China -20.7', NULL, NULL, 'A rematch from the 2020 super bowl consists of two teams that seem to be around the same area of the table at the end of each season. Olave Garden will look to find an answer to his rb troubles for the opening weeks as GWC will want to put their name back to the top.'),
  ('b78d5c45-f335-464b-819e-ef048a0892d2', '82a261cf-cca7-4d69-a333-f6776f06bf0f', 5, 'SNF America’s Game of the Week (NBC)', 'Code Monkey', 'Meet the Stevensons', NULL, NULL, 'Monkey -1.3', NULL, NULL, 'The biggest rivalry in the league will once again headline opening week. Code Monkey won this matchup comfortably last season but the celebrations soon came to an end as their season quickly went downhill. After losing this matchup, The Stevensons became active on the trade block resulting in their most successful season. These two have been going at it since birth and they simply don’t like each other.'),
  ('ddb98201-0f67-4b17-986c-f99787beb2e3', '82a261cf-cca7-4d69-a333-f6776f06bf0f', 6, 'MNF (ESPN)', 'YoungBoys Lover', 'Los Angeles Akers', NULL, NULL, 'Akers -2.4', NULL, NULL, 'The LA Akers look to build on their success from last year and use their momentum to win their opening week matchup. The Catholic Priests from Boston want to spoil commish’s opening week as they look to take advantage of their opponent.')
ON CONFLICT (article_id, position) DO NOTHING;

-- 2023/week-one-recap.mdx
INSERT INTO articles (id, season_year, week_number, kind, slug, title, summary, intro_markdown, outro_markdown, status, published_at, author_id, author_slug)
VALUES ('72ff2a8b-30fb-4129-91f6-54aa793d6b7d', 2023, 1, 'recap', '2023/week-one-recap', 'Week 1 Recap', 'In Week 1, the defending champions Cookin'' It Up narrowly defeated the Disney Pixar Baddies, Olave Garden surprised as underdogs with a high-scoring victory, Code Monkey dominated their rivalry game against Meet the Stevensons, and the Los Angeles Akers defeated YoungBoys Lover, showing promise for the season ahead.', NULL, NULL, 'published', '2023-09-12', NULL, NULL)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO article_matchups (id, article_id, position, slot_label, away_team_name, home_team_name, away_record, home_record, line, away_score, home_score, body)
VALUES
  ('f5d9e21b-20a0-46c0-96bf-e000a51b6533', '72ff2a8b-30fb-4129-91f6-54aa793d6b7d', 1, NULL, 'Cookin’ It Up', 'Disney Pixar Baddies', '1-0', '0-1', NULL, 115.06, 103.44, 'The Baddies were able to put themselves in a position to beat the defending champs going into Monday night but found themselves disappointed as they couldn’t get the production needed from Josh Allen. CIU escaped with a 13 point win.'),
  ('8c8fa0d7-deeb-460b-8a31-936bf49be487', '72ff2a8b-30fb-4129-91f6-54aa793d6b7d', 2, NULL, 'Team ETERNAL PAIN', 'Chubbin N’ Grubbin', '1-0', '0-1', NULL, 113.48, 100.46, 'EP were able to jump to a lead to start Sunday’s games and stayed comfortable as CNG could only produce 6.7 points combined from their WR1 and WR2. Team EP will be happy with their 13 point win as they hope to look for a switch in culture for their organization.'),
  ('f38383d6-8035-47e4-9683-1636cd8f1446', '72ff2a8b-30fb-4129-91f6-54aa793d6b7d', 3, NULL, 'Team Drako', 'Drake and Travis', '0-1', '1-0', NULL, 58.78, 77.44, 'Our lowest scoring matchup this week as both teams combined for 136.18 which is lower than our highest scorer of the week. Team Drako, scoring a total of 58.78 points, will have to be worried moving forward and hope Kupp will available by week 5. Drake and Travis are not in the best spot as well after losing Dobbins for the season, but they’ll be getting Kelce back and 1-0 is better than 0-1.'),
  ('6106943a-2b4a-4020-975e-1f1cde373021', '72ff2a8b-30fb-4129-91f6-54aa793d6b7d', 4, NULL, 'Great Waller China', 'Olave Garden', '0-1', '1-0', NULL, 102.52, 142.44, 'Projected the lowest score of the week and being 20 point underdogs may have provided a spark to Olave Garden as they shocked the world and scored a league high 142.44 points. Their trajectory is only going up and they look like the team to beat.'),
  ('10dde760-2e32-4027-9a75-65cbfd151779', '72ff2a8b-30fb-4129-91f6-54aa793d6b7d', 5, NULL, 'Code Monkey', 'Meet the Stevensons', '1-0', '0-1', NULL, 126.34, 85.46, 'Our primetime game came to an underwhelming conclusion as Code Monkey once again blew out their league rival opening week. Last year’s runner ups 
will have work to do if they want to be a contender.'),
  ('94fcd3e1-4fc0-4ea4-806f-e9e0db9e7d04', '72ff2a8b-30fb-4129-91f6-54aa793d6b7d', 6, NULL, 'YoungBoys Lover', 'Los Angeles Akers', '0-1', '1-0', NULL, 122.84, 135.46, 'You can call the LA Akers the Boston Globe as they bring down the YoungBoys Lover opening week. The Akers were able to take advantage of Lover’s disappointing TNF and put up the second highest score of the week at 135.46. A lot of encouraging signs for the LA Akers as they hope to take a step forward from last season.')
ON CONFLICT (article_id, position) DO NOTHING;

-- 2023/week-two-preview.mdx
INSERT INTO articles (id, season_year, week_number, kind, slug, title, summary, intro_markdown, outro_markdown, status, published_at, author_id, author_slug)
VALUES ('1adfd0ae-d882-42f9-a985-7a3bffcc9a27', 2023, 2, 'preview', '2023/week-two-preview', 'Week 2 Preview', 'In a series of week 2 matchups, teams with varying records and motivations aim to rebound, assert themselves, and prove their worth in Week 2, with highlights including Chubbin N’Grubbin facing Youngboys Lover, Cookin’ It Up taking on Team ETERNAL PAIN, and a clash between Drake and Travis and Code Monkey.', NULL, NULL, 'published', '2023-09-15', NULL, NULL)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO article_matchups (id, article_id, position, slot_label, away_team_name, home_team_name, away_record, home_record, line, away_score, home_score, body)
VALUES
  ('c6c4a25d-6885-4507-b176-7cb8d158f10e', '1adfd0ae-d882-42f9-a985-7a3bffcc9a27', 1, 'TNF (Prime Video)', 'Chubbin N’Grubbin', 'Youngboys Lover', '0-1', '0-1', 'CNG -1.5', NULL, NULL, 'Two teams coming off a loss week 1 look to regroup and bounce back. Manager Kirk Broadbelt will want to find his inner Chris Hansen as he’ll look to beat his former roommate and go out with a win week 2.'),
  ('a18fed92-1b67-4563-9540-fd85a650cbb8', '1adfd0ae-d882-42f9-a985-7a3bffcc9a27', 2, '1:00 (CBS)', 'Cookin’ It Up', 'Team ETERNAL PAIN', '1-0', '1-0', 'CIU -9.3', NULL, NULL, 'Ever since Cookin’ It Up started his reign, Team EP hasn’t found much luck as they’ve been a bottom dweller since. Team EP wants to make a statement against the defending champs and move to 2-0. On the other hand, Cookin’ It Up wants to prove last week wasn’t a fluke and tell the league their team is for real.'),
  ('ce61fb70-ef5a-48e6-a9cf-9cd8e9e81807', '1adfd0ae-d882-42f9-a985-7a3bffcc9a27', 3, '1:00 (Fox)', 'Los Angeles Akers', 'Great Waller China', '1-0', '0-1', 'GWC -7.6', NULL, NULL, 'In the last six matchups, GWC is 5-1 against the LA Akers. They’ll hope to find their first win of the season this week. The Akers looked very good week 1. The commish looks to build on that great performance and find a way to beat an opponent they’ve had no luck beating in the past.'),
  ('6f19a2b3-2b88-4247-a48a-716eb2696c52', '1adfd0ae-d882-42f9-a985-7a3bffcc9a27', 4, '4:25 (CBS)', 'Drake and Travis', 'Code Monkey', '1-0', '1-0', 'D&T -15.4', NULL, NULL, 'Back in 2021, both team managers were going back and forth hoping they would meet each other in the championship. Code Monkey got left behind that year but they know the past is behind them as they’ll look to build on a strong performance from last week.'),
  ('b3426736-f618-480d-b847-219a9d3e6f80', '1adfd0ae-d882-42f9-a985-7a3bffcc9a27', 5, 'SNF (NBC)', 'Disney Pixar Baddies', 'Team Drako', '0-1', '0-1', 'DPB -11.5', NULL, NULL, 'After one of the worst performances I’ve ever seen from any team in this league, Team Drako will want to pull an 180 and find their first win. After an unlucky loss week 1, the Baddies will pregame hard as they prepare for primetime.'),
  ('721bd879-3b0a-4d6f-b6d1-f38ce0d2d976', '1adfd0ae-d882-42f9-a985-7a3bffcc9a27', 6, 'MNF (ESPN)', 'Olave Garden', 'Meet the Stevensons', '1-0', '0-1', 'MTS -5.4', NULL, NULL, 'Meet the Stevensons manager TJ had much to say in week 1’s post game press conference. TJ offered comments like, “I got soft a** competition in this league” and “This league sorry as h*ll”. After an underwhelming performance week 1, Meet the Stevensons put themselves as the villain of the league. They face the best performer of week 1, Olave Garden, as both teams have a lot to prove moving forward.')
ON CONFLICT (article_id, position) DO NOTHING;

-- 2023/week-two-recap.mdx
INSERT INTO articles (id, season_year, week_number, kind, slug, title, summary, intro_markdown, outro_markdown, status, published_at, author_id, author_slug)
VALUES ('6561a711-dea4-4506-9c1f-9466af63ab66', 2023, 2, 'recap', '2023/week-two-recap', 'Week 2 Recap', 'In Week 2 of their NFL fantasy matchups, YoungBoys Lover secured a victory against Chubbin'' N Grubbin, Cookin'' It Up narrowly defeated Team ETERNAL PAIN, Great Waller China emerged victorious against the Los Angeles Akers, Drake and Travis dominated Code Monkey, Disney Pixar Baddies secured their first win against Team Drako, and Meet the Stevensons outperformed Olave Garden despite injuries to key players.', NULL, NULL, 'published', '2023-09-20', NULL, NULL)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO article_matchups (id, article_id, position, slot_label, away_team_name, home_team_name, away_record, home_record, line, away_score, home_score, body)
VALUES
  ('f75e8347-88c0-47c2-81f1-3e44ac3b4a2d', '6561a711-dea4-4506-9c1f-9466af63ab66', 1, NULL, 'Chubbin’ N Grubbin', 'YoungBoys Lover', '0-2', '1-1', NULL, 102.36, 129.24, 'A great Thursday night gave YBL a slight lead going into Monday night. CNG could not catch the pedo due to a Nick Chubb season ending injury. YBL’s three receivers combined for 70.7 points leading their team to a victory.'),
  ('0e2bbcfa-056b-4e1d-b746-e0bcf4ddfa71', '6561a711-dea4-4506-9c1f-9466af63ab66', 2, NULL, 'Cookin’ It Up', 'Team ETERNAL PAIN', '2-0', '1-1', NULL, 121.2, 120.94, 'An eventful Sunday for both teams led to a  MNF player vs player matchup to decide the week’s result. After a Jamaal Williams’ hamstring injury, it seemed all hope was lost for CIT. But Najee Harris fell .3 points short for Team EP leading to a CIT win.'),
  ('0b2f6ae2-58a0-4394-82f8-ed4ad0f410bd', '6561a711-dea4-4506-9c1f-9466af63ab66', 3, NULL, 'Los Angeles Akers', 'Great Waller China', '1-1', '1-1', NULL, 124.3, 128.14, 'After losing Week 1, the 3x champ knew his team needed to step up this week. After an eventful Sunday where the win/loss percentages kept changing, the LA Akers were the more likely to win this matchup going into MNF. Unfortunately the Akers came up short due to a mediocre performance from Deshaun Watson. GWC is now 6-1 against the LA Akers in the last 7 times they’ve met.'),
  ('d0e97235-e904-4a78-bf4e-bf187266c288', '6561a711-dea4-4506-9c1f-9466af63ab66', 4, NULL, 'Drake and Travis', 'Code Monkey', '2-0', '1-1', NULL, 128.12, 101.4, 'Both teams coming off a win week 1 looked to improve their record to 2-0. D&T’s great TNF was too much for the injury-riddled Code Monkey team. D&T improves to 2-0 and is now second place.'),
  ('b109d060-ae16-47d4-8bb6-0d9eb676f760', '6561a711-dea4-4506-9c1f-9466af63ab66', 5, NULL, 'Disney Pixar Baddies', 'Team Drako', '1-1', '0-2', NULL, 129.86, 121.48, 'Both teams looking for their first win in this primetime matchup. DPB’s WR performances was too much for Team Drako as the Baddies improve to 1-1.'),
  ('7d44c2b4-b3f1-4aca-9dcd-66e29ecd3e83', '6561a711-dea4-4506-9c1f-9466af63ab66', 6, NULL, 'Olave Garden', 'Meet the Stevensons', '1-1', '1-1', NULL, 77.34, 121.38, 'MTS manager TJ had a lot to say leading to this game causing many to tune into this matchup. After dropping a league high 142 points week 1, OG disappointed with an abysmal 77 point performance. MTS cruised to a win but injuries to Barkley and St. Brown will have them worried going into next week.')
ON CONFLICT (article_id, position) DO NOTHING;

-- 2023/week-three-preview.mdx
INSERT INTO articles (id, season_year, week_number, kind, slug, title, summary, intro_markdown, outro_markdown, status, published_at, author_id, author_slug)
VALUES ('2d080f70-b94f-4f6b-91cd-50216551cefb', 2023, 3, 'preview', '2023/week-three-preview', 'Week 3 Preview', 'In Week 3 of NFL fantasy matchups, Team ETERNAL PAIN faces YoungBoys Lover in a crucial 1-1 showdown, Code Monkey hopes to rebound against Disney Pixar Baddies, Team Drako seeks their first win against Cookin’ It Up, and Meet the Stevensons and Los Angeles Akers prepare for another intense battle with the Akers aiming for revenge.', NULL, NULL, 'published', '2023-09-21', NULL, NULL)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO article_matchups (id, article_id, position, slot_label, away_team_name, home_team_name, away_record, home_record, line, away_score, home_score, body)
VALUES
  ('d5364880-49d3-48c1-aa87-9374b43a722d', '2d080f70-b94f-4f6b-91cd-50216551cefb', 1, 'TNF (Prime Video)', 'Team ETERNAL PAIN', 'YoungBoys Lover', '1-1', '1-1', 'YBL -15.4', NULL, NULL, 'A huge game for both teams as they’re both 1-1 to start the season. Team EP is coming off a heartbreaking loss last week, but team manager Amogh has confidence his men will bounce back. YBL has the highest projected score of the week at 132.2 and they’ll hope the ESPN projections are correct. There aren’t too many injury concerns for both these teams this week making this an entertaining matchup.'),
  ('78b4e3fa-bcb0-4e44-9716-852ca4cdd30a', '2d080f70-b94f-4f6b-91cd-50216551cefb', 2, '1:00 (CBS)', 'Code Monkey', 'Disney Pixar Baddies', '1-1', '1-1', 'DPB -1.9', NULL, NULL, 'Code Monkey’s depleted team could not get the job done last week. They’ll hope star RB A. Jones comes back as they’ll need help against a hot team of Baddies. The Baddies want to tell the league they’re looking for something long term by picking an important win week 3.'),
  ('dfb8a826-02a2-4584-aa87-671a3d37615e', '2d080f70-b94f-4f6b-91cd-50216551cefb', 3, '1:00 (FOX)', 'Team Drako', 'Cookin’ It Up', '0-2', '2-0', 'CIT -7.4', NULL, NULL, 'Team Drako, now 0-2, wants to shock everyone by picking up their first win against first place team CIT. The defending champs haven’t looked great to start the season, but they’ve gotten the job done. Team Drako manager Carter isn’t the most confident as of now, but a late surge of points in week 2’s matchup is giving hope going into week 3.'),
  ('420a253d-30c6-405b-9bf9-b59f0829dbcd', '2d080f70-b94f-4f6b-91cd-50216551cefb', 4, '4:25 (CBS)', 'Meet the Stevensons', 'Los Angeles Akers', '1-1', '1-1', 'Akers -4.9', NULL, NULL, 'Everytime these two teams face off, we know we’re in for a treat. In the last years’ regular season matchup, MTS beat the Akers by 0.1 points. In the semifinals, MTS vs LA Akers was decided on Monday Night with MTS once again escaping with a win. LA Akers will channel their inner Batman and look for vengeance in this all entertaining matchup.'),
  ('866d531a-816e-404d-a530-7726bfe19f55', '2d080f70-b94f-4f6b-91cd-50216551cefb', 5, 'SNF (NBC)', 'Olave Garden', 'Drake and Travis', '1-1', '2-0', 'D&T -13.5', NULL, NULL, 'This entertaining rivalry featuring former roommates always has us tuned in. Both teams have been successful these past years. I know it’s early in the season, but this game is a must win as it’ll set the tone for both teams moving forward.'),
  ('7e30a106-1ce9-4611-b339-7d3e88e67fe2', '2d080f70-b94f-4f6b-91cd-50216551cefb', 6, 'MNF (ESPN)', 'Great Waller China', 'Chubbin’ N Grubbin', '1-1', '0-2', 'CNG -0.9', NULL, NULL, 'GWC coming off a huge win against the Akers week 2 will hope the momentum carries against the struggling CNG. After losing their best player for the season, CNG made the first trade of the season acquiring Raheem Mostert. They need to him to fill the void if they want to remain relevant moving forward')
ON CONFLICT (article_id, position) DO NOTHING;

-- 2023/week-three-recap.mdx
INSERT INTO articles (id, season_year, week_number, kind, slug, title, summary, intro_markdown, outro_markdown, status, published_at, author_id, author_slug)
VALUES ('80af7d29-1a17-4e23-8bae-1968b0517e21', 2023, 3, 'recap', '2023/week-three-recap', 'Week 3 Recap', 'In the latest round of NFL fantasy matchups, Los Angeles Akers secured a vengeance-filled victory against AmOn Another Level, Team ETERNAL PAIN triumphed over Certified Boys Lover with a standout performance by Keenan Allen, Chubbin’ N Grubbin surprised Great Walker China with a league-high score, Cookin’ It Up continued their winning streak against struggling Team Drako, Code Monkey outperformed Disney Pixar Baddies in a closely contested battle, and Drake and Travis dominated Olave Garden, maintaining their undefeated record, while Olave Garden faced another disappointing week.', NULL, NULL, 'published', '2023-09-28', NULL, NULL)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO article_matchups (id, article_id, position, slot_label, away_team_name, home_team_name, away_record, home_record, line, away_score, home_score, body)
VALUES
  ('6f036539-2a6a-458e-ac60-a0f98eeb7071', '80af7d29-1a17-4e23-8bae-1968b0517e21', 1, NULL, 'AmOn Another Level', 'Los Angeles Akers', '1-2', '2-1', NULL, 105.88, 125.86, 'Historically, these teams have some of the closest and entertaining matchups, and this one didn’t disappoint. On Sunday, they were neck and neck with exciting and controversial plays from both teams. Going into Monday, both teams’ projected score was at 110. But it seemed the Akers were on a mission as all went right for them during the MNF games. The LA Akers looked for vengeance and vengeance they got by beating one of their league rivals 125-105. 
> **_NOTE:_**  Team owner TJ Nanugonda changed his team name from Meet the Stevensons to AmOn Another Level

**Next Up:**
LA Akers 2-1 vs D&T 3-0 | AmOn 1-2 vs CNG 1-2'),
  ('d3efd4cc-47cf-41d4-9e4a-05fa366c5eea', '80af7d29-1a17-4e23-8bae-1968b0517e21', 2, NULL, 'Team ETERNAL PAIN', 'Certified Boys Lover', '2-1', '1-2', NULL, 137.8, 111.6, 'After a heartbreaking loss in Week 2, Team EP’s manager Amogh seemed confident his players would bounce back. Facing a good CBL team, Team EP’s star WR Keenan Allen put up a monster 45 point performance. This and their Kicker/DST carried them past the pedo (I think he’s into young-men now), moving them to 2-1.
> **_NOTE:_**  Team owner Joseph Hong changed his team name from YoungBoys Lover to Certified Boys Lover (we have contacted the FBI)

**Next Up:**
EP 2-1 vs Drako 0-3 | CBL 1-2 vs GWC 1-2'),
  ('d9ff102a-003d-467f-b3c1-3e7a602e3f71', '80af7d29-1a17-4e23-8bae-1968b0517e21', 3, NULL, 'Great Walker China', 'Chubbin’ N Grubbin', '1-2', '1-2', NULL, 146.06, 150.68, 'Coming into this matchup CNG was 0-2 and without their star RB Nick Chubb for the year. It wasn’t looking good for them but they knew their roster can compete. Facing a strong GWC team, CNG put up a league’s season high 150 points on the backs of Raheem Mostert ‘s 45 points and all their skill positions scoring above 15 points. GWC came close by dropping the second highest point performance for this league’s season with 146, but they’ll have to move to 1-2 unluckily. 

**Next Up:**
CNG 1-2 vs AmOn 1-2 | GWC 1-2 vs CBL 1-2'),
  ('bae8a24d-e427-4f26-b461-10ad2acb0378', '80af7d29-1a17-4e23-8bae-1968b0517e21', 4, NULL, 'Team Drako', 'Cookin’ It Up', '0-3', '3-0', NULL, 99.06, 113.0, 'Coming into this matchup, Team Drako was last place and CIT was first place. Expecting a cake walk for CIT, both teams looked average at best with Team Drako projected to win going into MNF. Team Drako could not take advantage as their mediocrity continued with bad performances from Burrow and White. CIT continues his controversial run of wins and Team Drako is now the only team in the league that has not won a game. 

**Next Up:**
Drako 0-3 vs EP 2-1 | CIT 3-0 vs CM 2-1'),
  ('b0267e0a-8195-4601-9c9b-72ea83612ad6', '80af7d29-1a17-4e23-8bae-1968b0517e21', 5, NULL, 'Code Monkey', 'Disney Pixar Baddies', '2-1', '1-2', NULL, 141.98, 118.02, 'Coming off a tough week, Code Monkey faced a real test against the top scorer of week 2, the Baddies. Both teams came out firing in the early window but Code Monkey was able to find a slight lead. In the late window of games Code Monkey improved their lead and came out with a huge win. They’ll miss Mike Williams for the season but they’ll be expecting a return from their star RBs Jones and Ekeler. 

**Next Up:**
CM 2-1 vs CIT 3-0 | DPB 1-2 vs OG 1-2'),
  ('e09e7c20-236c-4bdd-921b-95dff8139497', '80af7d29-1a17-4e23-8bae-1968b0517e21', 6, NULL, 'Olave Garden', 'Drake and Travis', '1-2', '3-0', NULL, 111.16, 139.48, 'Two former roommates always had their fair share of battles but this matchup got ugly quick. D&T dominated the Sunday’s late window of games as OG failed to keep up. The three Eagles capped off a great week on MNF improving D&T to 3-0. Back to back weeks of struggle for Olave Garden as they hope key pieces will come back sooner than later.

**Next Up:**
D&T 3-0 vs LA Akers 2-1 | OG 1-2 vs DPB 1-2')
