INSERT INTO articles (id, season_year, week_number, kind, slug, title, summary, intro_markdown, outro_markdown, status, published_at, author_id, author_slug)
VALUES ('f11eceac-bb1e-4a5e-a0d0-ba9d4b18e2a8', 2023, 4, 'preview', '2023/week-four-preview', 'Week 4 Preview', 'In a critical week of NFL fantasy matchups, struggling teams seek crucial wins, including Disney Pixar Baddies facing Olave Garden, Team Drako taking on Team ETERNAL PAIN, Chubbin’ N Grubbin clashing with AmOn Another Level, Los Angeles Akers challenging the undefeated Drake and Travis, Certified Boys Lover against Great Waller China in a prideful showdown, and Cookin’ It Up aiming to maintain their winning streak against a resilient Code Monkey team.', NULL, NULL, 'published', '2023-09-29', NULL, NULL)
