INSERT INTO article_matchups (id, article_id, position, slot_label, away_team_name, home_team_name, away_record, home_record, line, away_score, home_score, body)
VALUES
  ('146799cc-e3ae-4833-80a4-97ba3b5defa9', 'f11eceac-bb1e-4a5e-a0d0-ba9d4b18e2a8', 1, 'TNF (Prime Video)', 'Disney Pixar Baddies', 'Olave Garden', '1-2', '1-2', 'DPB -9.1', NULL, NULL, 'Two former state champs play in this must win game that may decide their season’s trajectory. These two teams have not been able to get that Enloe Tennis winning culture as they struggle for wins. For the Baddies, this game is their most important as bye week trouble looms ahead. OG needs this win for much needed momentum as they’ll continue to get their star players back from injury.'),
  ('a1442493-6d8e-40f7-8a28-c68d4324097f', 'f11eceac-bb1e-4a5e-a0d0-ba9d4b18e2a8', 2, '1:00 (FOX)', 'Team Drako', 'Team ETERNAL PAIN', '0-3', '2-1', 'EP -9.7', NULL, NULL, 'These two teams have struggled in the past two years and they’ve both been close to the bottom than the top. Team EP has proven his team is ready to compete for something special. But Team Drako continues their struggle to find any bit of hope for the postseason.'),
  ('3e430251-ee07-40d0-bf76-ad42a51652a4', 'f11eceac-bb1e-4a5e-a0d0-ba9d4b18e2a8', 3, '1:00 (CBS)', 'Chubbin’ N Grubbin', 'AmOn Another Level', '1-2', '1-2', 'CNG -9.3', NULL, NULL, 'This is a must win for both teams as they are below .500. CNG will hope last week’s performance will carry over. AmOn will want to see something different from his team as they’ll need this win for their confidence.'),
  ('8443491a-2c66-4cdd-9a7a-c08bd099322f', 'f11eceac-bb1e-4a5e-a0d0-ba9d4b18e2a8', 4, '4:25 (FOX)', 'Los Angeles Akers', 'Drake and Travis', '2-1', '3-0', 'D&T -4.8', NULL, NULL, 'After a terrific performance week 3, Drake and Travis will have a tough test against a very good LA Akers team. The LA Akers hope to continue this consistent run of high scoring weeks and do enough to give the red hot D&T their first loss.'),
  ('f9bec882-58cc-43aa-a3aa-b63317805132', 'f11eceac-bb1e-4a5e-a0d0-ba9d4b18e2a8', 5, 'SNF (NBC)', 'Certified Boys Lover', 'Great Waller China', '1-2', '1-2', 'GWC -1.6', NULL, NULL, 'This matchup is much more than some fantasy football game. Their pride and heritage are on the line. If you lose this game, I don’t know if your family can talk to you anymore. The Lover Boy (who likes young-men) wants to make sure this war is not a tie as he looks to get an important win in primetime. But Great Waller China will not make it easy as they look to spread their communist ideals across the world. Projected the highest scoring matchup of the week, this game is the world’s game of the week.'),
  ('05d88224-3fbd-45e7-a9e5-a33450a65d03', 'f11eceac-bb1e-4a5e-a0d0-ba9d4b18e2a8', 6, 'MNF (ESPN)', 'Cookin’ It Up', 'Code Monkey', '3-0', '2-1', 'CIT -1.0', NULL, NULL, 'The defending champ will look to stay at the top as they play a tough Code Monkey team. After losing their star WR, Code Monkey will hope their next man can do enough for a win. This may be our closest matchup of the week, and it may come down to SNF.')
ON CONFLICT (article_id, position) DO NOTHING;

