INSERT INTO articles (id, season_year, week_number, kind, slug, title, summary, intro_markdown, outro_markdown, status, published_at, author_id, author_slug)
VALUES ('0d298542-cd47-45f0-8903-b9a75bbf1287', 2023, 4, 'recap', '2023/week-four-recap', 'Week 4 Recap', 'In Week 4 of the fantasy football season, Drake and Travis continue their dominant run with a convincing win over Los Angeles Akers, Team ETERNAL PAIN defeats Team Drako in a low-scoring matchup, Certified Boys Lover secures a strong victory against Great Waller China, AmOn Another Level earns a decisive win over Chubbin'' N Grubbin, Cookin'' It Up maintains their undefeated record with a dominant performance against Code Monkey, and Olave Garden prevails over Disney Pixar Baddies in a high-scoring matchup.', NULL, NULL, 'published', '2023-10-05', NULL, NULL)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO article_matchups (id, article_id, position, slot_label, away_team_name, home_team_name, away_record, home_record, line, away_score, home_score, body)
VALUES
  ('5bd4b7ae-1a5e-4c19-8ae9-56f579229bd7', '0d298542-cd47-45f0-8903-b9a75bbf1287', 1, NULL, 'DRAKE AND TRAVIS', 'Los Angeles Akers', '4-0', '2-2', NULL, 164.66, 119.72, 'A matchup featuring two top three teams coming into the week ended up being lop sided and anticlimactic. Every-time teams got into the redzone, it seemed D&T’s players were scoring touchdowns. D&T finished the game quick as Akers RB Cmac’s 50 point performance couldn’t even make it interesting. 

**Next Up:**
D&T 4-0 vs CNG 1-3 | LA Akers 2-2 vs DPB 1-3'),
  ('f0651048-3a3a-4872-9e0f-2abee31f0cbb', '0d298542-cd47-45f0-8903-b9a75bbf1287', 2, NULL, 'TEAM ETERNAL PAIN', 'Team Drako', '3-1', '0-4', NULL, 120.12, 88.7, 'One of our projected low scoring matchups went as predicted. Both teams couldn’t find a huge boom from one of their players but Team EP’s versatility made the difference. Getting double digit points from every player, but the defense and kicker, was too much for the struggling Team Drako.

**Next Up:**
Team EP 3-1 vs GWC 1-3 | Team Drako 0-4 vs Code Monkey 2-2'),
  ('aabd8a22-3729-4ea5-a0cc-2deb85e6dc70', '0d298542-cd47-45f0-8903-b9a75bbf1287', 3, NULL, 'CERTIFIED BOYS LOVER', 'Great Waller China', '2-2', '1-3', NULL, 161.5, 108.82, 'In this tense matchup, CBL showed the league that pressure is a privilege as they put up their best performance of the year. Led by their first overall picks JJetas, and starters K. Williams and Ant Rich, CBL was able to streamroll themselves into fourth place on the table. 

CBL 2-2 vs AmOn 2-2 | GWC 1-3 vs Team Ep 3-1'),
  ('5e890a35-d87a-459c-80fe-dea9a2575870', '0d298542-cd47-45f0-8903-b9a75bbf1287', 4, NULL, 'AMON ANOTHER LEVEL', 'Chubbin’ N Grubbin', '2-2', '1-3', NULL, 124.54, 61.96, 'After a name change, AmOn’s team manager was able to talk the talk and walk their walk by getting a huge win. Led by Puka, AmOn’s team was too much for a lackluster week from CNG. After a great week 3, a reality check was given to CNG. They’ll look to bounce back against the undefeated D&T next week.

**Next Up:**
AmOn 2-2 vs CBL 2-2 | CNG 1-3 vs D&T 4-0'),
  ('2616e209-1416-4cbe-be7d-f3c93feecdf8', '0d298542-cd47-45f0-8903-b9a75bbf1287', 5, NULL, 'COOKIN’ IT UP', 'Code Monkey', '4-0', '2-2', NULL, 163.38, 85.52, 'Everything went well for CIT this week as they outscore their opponent by 81. Code Monkey needs help as they’ll look to get healthy for an important matchup against winless Team Drako next week.

**Next Up:**
CIT 4-0 vs OG 2-2 | CM 2-2 vs Drako 0-4'),
  ('41d23525-c98a-4fbb-9cec-ad8782d47d2d', '0d298542-cd47-45f0-8903-b9a75bbf1287', 6, NULL, 'OLAVE GARDEN', 'Disney Pixar Baddies', '2-2', '1-3', NULL, 140.58, 121.2, 'They might’ve written off Olave Garden, but OG didn’t write back as they boom for 140. Led by unlikely heroes DMont and Kmet, they were able to hold off a talented team of Baddies. It wasn’t a bad week for the Baddies, but health and bye week trouble will be a concern for a must win matchup against their league rival in Week 5. 

**Next Up:**
OG 2-2 vs CIT 4-0 | DPB 1-3 vs LA Akers 2-2')
ON CONFLICT (article_id, position) DO NOTHING;

