INSERT INTO articles (id, season_year, week_number, kind, slug, title, summary, intro_markdown, outro_markdown, status, published_at, author_id, author_slug)
VALUES ('dc1e7482-e258-4b52-979d-6616a8357db5', 2023, 5, 'preview', '2023/week-five-preview', 'Week 5 Preview', 'In Week 5 of Cary Bengals fantasy matchups, struggling teams aim to turn their season around, with notable games including Code Monkey facing Team Drako in a TNF matchup between two teams dealing with player issues, Drake and Travis looking to maintain their undefeated record against Chubbin N’ Grubbin, and a Sunday night shootout between Olave Garden and Cookin’ It Up, while Los Angeles Akers seek redemption against Disney Pixar Baddies on Monday night.', NULL, NULL, 'published', '2023-10-06', NULL, 'keshav')
ON CONFLICT (slug) DO NOTHING;

INSERT INTO article_matchups (id, article_id, position, slot_label, away_team_name, home_team_name, away_record, home_record, line, away_score, home_score, body)
VALUES
  ('4d98876a-97e9-4f4f-bb35-0207ee7b6df1', 'dc1e7482-e258-4b52-979d-6616a8357db5', 1, 'TNF (Prime Video)', 'Code Monkey', 'Team Drako', '2-2', '0-4', 'Drako -10.8', NULL, NULL, 'Perfect for TNF, two poverty stricken teams in recent history face off in week 5. Team Drako has its sights on wins as their first round pick Cooper Kupp will likely return to action this week. Code Monkey has two starters out this week with no remarkable players left in the lineup outside of Mahomes.'),
  ('7f514026-0bdf-43c7-94c1-cb743db4b2d2', 'dc1e7482-e258-4b52-979d-6616a8357db5', 2, '1:00 (CBS)', 'Drake and Travis', 'Chubbin N’ Grubbin', '4-0', '1-3', 'D&T -17.9', NULL, NULL, 'Chubbin N’ Grubbin put up a 61 point dud last week (21 points from Jags D) and faces a Drake and Travis team that has been firing on all cylinders. Since Chubb’s injury no player has stepped up enough to warrant a name change. Kirk hopes that changes this week. If Drake and Travis keeps scoring TDs at the rate they’ve been, it won’t matter how good the other team performs.'),
  ('40a47dc0-8ba6-4dc9-b299-1072be7b3fec', 'dc1e7482-e258-4b52-979d-6616a8357db5', 3, '1:00 (FOX)', 'Team ETERNAL PAIN', 'Great Waller China', '3-1', '1-3', NULL, NULL, NULL, 'Team ETERNAL PAIN has started off strong this season and added a PPR cheat code Alvin Kamara along the way. They hope to continue their 2 game win streak against a somewhat unlucky Great Waller of China team that has the most PA.'),
  ('35a2caf8-a78b-4994-8872-4d494870daf2', 'dc1e7482-e258-4b52-979d-6616a8357db5', 4, '4:25 (FOX)', 'AmOn Another Level', 'Certified Boys Lover', '2-2', '2-2', 'GWC -4.1', NULL, NULL, 'The Certified Boys Lover should be pumped up this week with Drizzy dropping entering the weekend. They hope to take advantage of a middling AmOn Another Level team with a lot of injury designations entering Thursday night.'),
  ('85a44526-95f1-4aa6-918a-33e3782bf5aa', 'dc1e7482-e258-4b52-979d-6616a8357db5', 5, 'SNF (NBC)', 'Olave Garden', 'Cookin’ It Up', '2-2', '4-0', 'OG -10.4', NULL, NULL, 'We may have a shootout on our hands as these two teams both dropped over 140 last week. Olave Garden needs some of their highly drafted players to live up to their expectations to pull this one out. Cookin’ It Up looks to survive another week at the top of the table during a week without QB1.'),
  ('0befdd3c-16bd-437f-bca6-83c9526af618', 'dc1e7482-e258-4b52-979d-6616a8357db5', 6, 'MNF (ESPN)', 'Los Angeles Akers', 'Disney Pixar Baddies', '2-2', '1-3', 'Akers -10.2', NULL, NULL, 'Baddies manager Sam Nangali comes in peace this year, with a nonchalant management style. Team Akers wants all the smoke. The Akers hope to bounce back after a disappointing loss to stay above .500. This is also a crucial game for the Baddies as it may be tough to recover from a 1-4 start.')
ON CONFLICT (article_id, position) DO NOTHING;

-- 2023/week-five-recap.mdx
INSERT INTO articles (id, season_year, week_number, kind, slug, title, summary, intro_markdown, outro_markdown, status, published_at, author_id, author_slug)
VALUES ('ec0fa616-8b48-4923-9efa-03aafab2fd01', 2023, 5, 'recap', '2023/week-five-recap', 'Week 5 Recap', 'In Week 5 of the fantasy football season, Team Drako secures their first win of the season against Code Monkey, Drake and Travis maintain their undefeated streak by defeating Chubbin N’ Grubbin, Team ETERNAL PAIN loses to Great Waller China, AmOn Another Level dominates Certified Boys Lover, Olave Garden wins convincingly against Hammy Heroes, and Los Angeles Akers fall to Disney Pixar Baddies in their rivalry matchup.', NULL, NULL, 'published', '2023-10-12', NULL, 'revanth')
ON CONFLICT (slug) DO NOTHING;

INSERT INTO article_matchups (id, article_id, position, slot_label, away_team_name, home_team_name, away_record, home_record, line, away_score, home_score, body)
VALUES
  ('205564e7-04ce-4f7d-ad67-bbf3d8fb2ab3', 'ec0fa616-8b48-4923-9efa-03aafab2fd01', 1, NULL, 'Code Monkey', 'Team Drako', '2-3', '1-4', NULL, 86.84, 118.86, 'In a matchup featuring two of the worst teams from the 2022-2023 season, dubbed the “veggie bowl”, showcased veggie performances across the field. Team Drako, after a blockbuster deal highlighted by trading away his first round pick Cooper Kupp in return for a booming Stefon Diggs was able to take down team Monkey with solid performances across the board. Monkey, faced with rb injuries/bye week, trotted out a player who got cut immediately the day after his game (💀). 
Team Drako, getting his first win of the season, looks to continue the momentum from this week 5 matchup against a red hot Olave Garden in week 6.
Code Monkey may need to unit test their code, as their draft strategy has not paid off so far, and may need to look into some roster changes before he ends up in the same position as last year. He will hope his fortunes turn around with the return of his LinkedIn connection and first round pick Austin Ekeler next week in a tough matchup against Team ETERNAL PAIN.'),
  ('a356dcb9-5f8f-4fe1-97ac-d3df55f9dcb6', 'ec0fa616-8b48-4923-9efa-03aafab2fd01', 2, NULL, 'Drake and Travis', 'Chubbin N’ Grubbin', '5-0', '1-4', NULL, 147.72, 99.72, 'This matchup showcased teams who find themselves in week 6 at opposite ends of the power rankings. Rivals during their time as apartment mates, we know there would be no love lost in this matchup. Grubbin disappointed again after such high hopes after the week 3 performance saw him drop (at the time) a league-high 150 points. Drake and Travis continued their path of domination across their foes by putting up nearly 150 points behind their positional advantage, as their QB and TE gave them 50 points, something they believe can be relied upon as the season progresses.
Chubbin N’ Grubbin, off the back of two uncharacteristic and dissappointing performances find themselves in a position they aren’t accustomed to in their short tenure as a part of the Cary Bengals league. They look to shake things up by trading for Justin Jefferson, in what some may consider a questionable deal given the position they find themselves. Some sources suggest that he only made the trade so he could change his name to get over the loss of his pookie Nick Chubb. They will face off against the Disney Pixar Baddies in week 6 in a close to must-win matchup if they hope to make the playoffs.
Drake and Travis look like the most consistently good team in the league, averaging over 131 points per game so far this season. However, they may be treading harsher water as they now deal with injuries to their stud TE Kelce and emerging RB Achane. Drake and Travis will take on another apartment-mate in Week 6 as they look to administer conversion therapy against the Certified Boys Lover'),
  ('d2310f83-59c9-410f-b30a-bce9da7cdf4d', 'ec0fa616-8b48-4923-9efa-03aafab2fd01', 3, NULL, 'Team ETERNAL PAIN', 'Great Waller China', '3-2', '2-3', NULL, 99.64, 115.28, 'In a battle against pantheon greats in Cary Bengals league history, the 3x champ took the edge over the 2x champ. GWC stood tall and firm like the Great Wall of China and made the proud EP fall in a much needed win for GWC. The namesake of the GWC finally had a boom game along with a great performance from Travis Etienne to lift GWC over EP, who had poor performances, given their standards, from most of their players.
Team Waller China will gladly take the win, but it came with a cost as they lose a key performer James Connor, who will be on IR for the next few weeks. GWC will need to find another piece to replace the production Connor was delivering so far this season. GWC will look for his week 5 performers to keep it up against a feisty AmOn Another Level team in week 6.
Team Eternal Pain had a down week but will hope his stud WR Keenan Allen along with the continued production of Kamara will propel him back to the win column over a struggling Code Monkey team.'),
  ('8d5885ea-6644-4152-b473-dbb666991f97', 'ec0fa616-8b48-4923-9efa-03aafab2fd01', 4, NULL, 'AmOn Another Level', 'Certified Boys Lover', '3-2', '2-3', NULL, 141.64, 70.02, 'As fellow Panthers fans, this matchup started off with amiableness, as they could sympathize with each other over how shit their favorite NFL team looked. However, once the cleats were laced up, the pads were put on, and helmets were in place, all feelings of fondness quickly dissipated, as team AmOn Another Level was on a mission from the whistle. There was worry coming into this matchup for team AmOn, as they were dealing with injury trouble with their 1st and 2nd round draft pick, but Team Another Level took the doubt and hate to heart, as they dominated this matchup with AmOn’s best performance this season. This matchup started off with bang in TNF, as AmOn’s DJ Moore erupted for a 49 point performance, and the momentum carried with them to Sunday. Unlikely heroes Dallas Goedert and Rashee Rice put up great performances to thrust Team Another Level past the Boys Lover.
On the other hand, everything seemed to go wrong, or should I say straight, for the Boys Lover, starting with the CBL’s favorite NFL team, the Panthers, getting beat down by the Lions. There was some positive that could be taken from this, as waiver wire pickup LaPorta boomed this game, looking like a possible top 3 TE in fantasy ROS. However, bad went to worse, as their other players dropped duds, and worse went to worst, as the #1 overall draft pick Justin Jefferson went out with an injury late in the game, and was later announced to be placed on IR for a hamstring injury. And to make matters worse, their young and upcoming QB Anthony Richardson also got hurt in his game, forcing him to IR for possibly up to 8 weeks. Team Boys Lover, shocked by the loss of their best player, could not rally the troops, and scored an abysmal 70 points in the wake of the loss of JJ.
AmOn Another Level found ways to get the win, regardless of the player, the sign of great teams in sports. However, it is yet to be seen if that translates to Another Level’s Fantasy Team. They hope to get back their two studs Barkley and St. Brown in a matchup against a Waller China team that looks better going into week 6
Certified Boys Lover may need to consider switching sides into the realm of heterosexuality to induce a culture change, as their bad injury luck from the past seasons bites them once again. Team Boys Lover grudgingly departed from their 1st round pick in order to build some more depth, and we will see if that strategy pays off next week when they take on the mighty Drake and Travis who look to keep their undefeated record alive.'),
  ('7ec30122-8264-4838-8e5f-78412e2645a1', 'ec0fa616-8b48-4923-9efa-03aafab2fd01', 5, NULL, 'Olave Garden', 'Hammy Heroes', '3-2', '4-1', NULL, 176.58, 107.34, 'Team OG gave team heroes a side of breadsticks with the main course of ass whoopin, as OG went nuclear for a season high 176.58 points to give Hammy Heroes his 🥖st loss. Catapulted by a week high 52.2 points from Jamar Chase, team Garden got great performances from almost every single player on his team. A bounce back performance from Breece Hall and another strong performance from Montgomery was too much to handle for the Hammy Heroes, as they struggled to find points from their counterpart RBs. Hoping for some brotherly love, team Heroes played James and Dalvin Cook, but to no avail, as they only combined for 7.4 points. Some missed chances from their Ravens stack hurt them as well, as Andrews and Flowers had key drops, which may not have won Heroes the week, but could’ve have given the team a better outlook moving forward.
Team Olave Garden looks to have gotten past some early turbulence and has shot up to the #2 spot in three weekly power rankings. Their depth is formidable and players on their bench seeming to only get better as time passes due to getting more opportunities (Palmer, Taylor, Addison), this looks like a team that has something to prove moving forward and hopes to start a streak of wins against relatively weaker opponents (in the eyes of the media, not in the eyes of Olave Garden), firstly starting with Team Drako next week.
Hammy Heroes (formerly named Cookin’ it Up) looks to switch up the culture, as they believe the friendliness/brotherliness of the former roster and success from past seasons may be causing the team to ease up a bit. GM Sparsh Patel even proclaimed in the Week 4 Postgame interview that they “don’t think they have the best team in the league” persay, and after an embarrassing loss in week 5 by almost 70 points, they hope that this loss will act as a wake up call for team Heroes. Team Heroes will need more than just motivation though, as they have struggled immensely to find production from the RB2 position, and likely needs to look to make moves to bolster up a clear weakness. However, even after a rough week, there are still many good signs for the heroes. They picked up Cooper Kupp in a trade, who despite some age and injury concerns, looked like his old self, with a great performance in his return to the gridiron. Also, the Heroes still have the 2nd best record in the league, so they are far from panick mode despite a lackluster performance. Hammy Heroes will look to bounce back in week 6 when they take on the commish.'),
  ('d55a698e-2704-40b0-9e9f-caec1c33fe72', 'ec0fa616-8b48-4923-9efa-03aafab2fd01', 6, NULL, 'Los Angeles Akers', 'Disney Pixar Baddies', '2-3', '2-3', NULL, 96.64, 120.06, 'These two close friends and rivals battled it out in a matchup that once again saw the GM of the Baddies take down the commish. GM of Baddies Samvit (🤓) Nangali took a humble approach this year against most of his opponents this year, likely inspired by the all time great Roger Federer and his mannerisms to his opponents, but when it comes to competing against GM of the Akers Rishi Nookala, Sam will use whatever technique he needs to to get the edge, even instigating bodily pain and monetary loss. This time, Disney Pixar Baddies entranced and bewitched the Akers players, and took advantage of flat performance to get their second win of the season.
The Baddies seem to have team Akers’ number, as they once again are able to capture a win in this heated rivalry. Another week, another Tyreek Hill monster game, which along with a proliferant Bills stack of Allen and Davis, was enough to dispatch of the Akers. Although team Baddies are dealing with minor injury concerns, they will get back one of their superstar players Mike Evans after a bye week, and will hope to rack up another win against a struggling Chubbin N’ Grubbin team.
Team Akers had a pretty uninspiring performance, and other than a great bounce back game from Calvin Ridley, was not able to get much from his other players. His MVP so far, Christian McCaffrey, was bottled up and due to an unlucky fumble and Jordan Mason stolen TDs, was unable to carry the Akers like the weeks past. It wasn’t a horrible performance by any means, but team Akers will need better showings from his talented team to hope to compete for a championship. After two tough losses to two of their biggest rivals, team Los Angeles Akers has another tough matchup against the Hammy Heroes, and will need to pickup a win in order to avoid a concerning 3 game slump.')
ON CONFLICT (article_id, position) DO NOTHING;

-- 2023/week-six-preview.mdx
INSERT INTO articles (id, season_year, week_number, kind, slug, title, summary, intro_markdown, outro_markdown, status, published_at, author_id, author_slug)
VALUES ('62fc4b7f-7ecb-4c96-8f39-656411041ad2', 2023, 6, 'preview', '2023/week-six-preview', 'Week 6 Preview', 'In Week 6 of the fantasy football season, the defending champion Hammy Heroes face the Los Angeles Akers in a crucial matchup, Team Drako and Olave Garden clash in a high-scoring battle, JJ Waiting Room trades for Justin Jefferson but faces the Disney Pixar Baddies who are coming off a win, Certified Boys Lover aims to bounce back against the undefeated Drake and Travis, Code Monkey and Team ETERNAL PAIN, both looking to improve from last season, face off in a primetime showdown, and Great Waller China seeks to challenge AmOn Another Level in a closely projected Monday night matchup.', NULL, NULL, 'published', '2023-10-13', NULL, NULL)
ON CONFLICT (slug) DO NOTHING;

INSERT INTO article_matchups (id, article_id, position, slot_label, away_team_name, home_team_name, away_record, home_record, line, away_score, home_score, body)
VALUES
  ('c403f5a5-e56a-46e9-acd9-223cfae924fc', '62fc4b7f-7ecb-4c96-8f39-656411041ad2', 1, 'TNF (Prime Video)', 'Hammy Heroes', 'Los Angeles Akers', '4-1', '2-3', 'HH -4.1', NULL, NULL, 'The defending champ suffered their first loss of the season last week after getting steamrolled by Olave Garden. They’ll have to face off against the LA Akers this week. After a strong start to the season, the Akers have dropped back to back games and put up a sub 100 point performance against their league rival. Both teams want a bounce back victory, but the pressure will certainly be on the Commish’s team as a loss here will put them close to the bottom.'),
  ('0b99df57-1492-41e1-819b-6111225e82ce', '62fc4b7f-7ecb-4c96-8f39-656411041ad2', 2, '1:00 (FOX)', 'Team Drako', 'Olave Garden', '1-4', '3-2', 'Drako -3.4', NULL, NULL, 'Both teams coming off their highest points of the season last week as Team Drako got their first win and OG put up the league’s highest point total this season. Team Drako will look to ride their momentum by beating a strong OG team. OG wants to prove they belong at the top by repeating their performance from last week. Projecting as one of the highest scoring matchups of the week, Team Drako is shockingly favored coming into this week.'),
  ('ed845f8a-de63-454b-bf0a-d5f1aad67d42', '62fc4b7f-7ecb-4c96-8f39-656411041ad2', 3, '1:00 (CBS)', 'JJ Waiting Room', 'Disney Pixar Baddies', '1-4', '2-3', 'JWR -1.6', NULL, NULL, 'After a shocking performance last week, JWR made a trade for this year’s #1 pick Justin Jefferson, but will be without him for four weeks due to injury. Many are questioning their decision as they need wins right now. On the other hand, the Baddies are coming off their annual win against their league rival LA Akers, and will look to improve as important players are coming off their bye week. This matchup is a must win for both teams as they’re both under .500, but JWR cannot fall into a deeper hole.'),
  ('c38310ae-54e3-4102-935c-caa3c64038f6', '62fc4b7f-7ecb-4c96-8f39-656411041ad2', 4, '4:25 (FOX)', 'Certified Boys Lover', 'Drake and Travis', '2-3', '5-0', 'D&L -17.1', NULL, NULL, 'Make that 5 for 5 for Drake and Travis as they are now the only undefeated team left. They will be the huge favorite against a struggling CBL. The Heterophobe traded away their best player JJettas because of his recent injury. Looking to pickup some wins now, they’ll have a tough task beating the red hot Drake and London.'),
  ('43e6cd92-6d64-41fe-97a3-96bed2db800f', '62fc4b7f-7ecb-4c96-8f39-656411041ad2', 5, 'SNF (NBC)', 'Code Monkey', 'Team ETERNAL PAIN', '2-3', '3-2', 'Team EP -0.7', NULL, NULL, 'This week’s primetime matchup features last year’s bottom two teams. Both managers are sure last year was a fluke but Code Monkey has been struggling. On the other hand Team EP has found their stride, even though they lost last week, by being above .500 at this point. Code Monkey, coming off back to back losses, will have their #1 pick Austin Ekeler coming back as they’ll need a win this week.'),
  ('9cb27ae8-0837-4bf6-b71a-4c7e809bd69d', '62fc4b7f-7ecb-4c96-8f39-656411041ad2', 6, 'MNF (ESPN)', 'Great Waller China', 'AmOn Another Level', '2-3', '3-2', 'AmOn -1.2', NULL, NULL, 'After losing week 3 to the Commish, AmOn’s manager TJ had a lot to say to and about the league in the press conference. His words seemed to work as his team are coming off back to back wins. His opponent, the 3x champ, got a must needed win against their league rival last week. GWC is looking for a way to get back to the top but AmOn will stand in their way. This is one for the closest projected matchups of the week.')
ON CONFLICT (article_id, position) DO NOTHING;

