VALUES ('9ecc626c-04e6-4bf6-abd1-0ca1e1e4bf0f', 2024, 1, 'preview', '2024/week-one-preview', '2024 Week 1 Preview', 'Week 1 of the 2024 Cary Bengals season kicks off with six fresh matchups as every team looks to start the year on the right foot.', NULL, '> **_NOTE:_**  Matchup of the week and the headliner matchup will have a post game press conference', 'published', '2024-09-05', NULL, NULL)
