INSERT INTO article_matchups (id, article_id, position, slot_label, away_team_name, home_team_name, away_record, home_record, line, away_score, home_score, body)
VALUES
  ('d8172bd3-e3cd-4907-85f3-abb15942c1e7', '9ecc626c-04e6-4bf6-abd1-0ca1e1e4bf0f', 1, 'TNF OPENING NIGHT (NBC) 🎆🎆🎆', 'Kupp Kupp and Away!', 'London is Red', NULL, NULL, 'KKaA -0.9', NULL, NULL, 'KKaA travel to Boston to take on London is Red on Opening Night at the legendary Fenway Park. The 2x league champions are coming off a runner up finish in last year’s campaign. Mr. Patel previously said second place is the first loser and his team will play with that edge from Week 1. They are led by the eagle duo in Brown and Barkley with a mix of veteran leadership and youthful verve in Kupp and ARich. After London is Red’s disappointing season last year, the commish has decided to relocate his team to title-town to maybe change the fortunes of his team moving forward. The gooners are led by their strong receiving core in Lamb, London and Samuel added with their down-hill run-game in Derrick Henry. Fenway Park will be roaring knowing how long Boston waited for a CBFFL team, but KKaA will be the slight favorite due to their strength in every area of the field.'),
  ('97c76c1f-9440-459c-8bab-89957a713f95', '9ecc626c-04e6-4bf6-abd1-0ca1e1e4bf0f', 2, 'Friday Night in Canada (Peacock) 🇨🇦🍁', 'My Puka Bear', 'JJ Phoenix Rising In…', NULL, NULL, 'MPB -1.7', NULL, NULL, 'MPB and JJPRI travel to Montreal to feature in the league’s first Canada game. Many are saying the 3x Champs are washed and past their prime but everyone in the league knows how scary Mr. Bao’s team can be on any given week. After not making the playoffs for a second consecutive year, MPB will feel like this is a make or break season. MPB is led by JT and Puka Nacua and they’ll look to start their season with a win. After making the playoffs for three consecutive years, JJPRI went for a championship last season. Due to inconsistent performances from their higher ceiling players and some questionable roster moves, Mr. Broadbelt’s team finished in 11th place. This season JJPRI will not have to wait for JJ and with the aid of higher floor players in Kelce and Hurts, they’ll look to start the season off with much needed momentum going forward. Both teams will be allowed to wear their team colors in this matchup and MPB will be the favorite by 1.7 points.'),
  ('6609814b-6a1e-458d-80e9-8a07f463c946', '9ecc626c-04e6-4bf6-abd1-0ca1e1e4bf0f', 3, '1:00 (CBS) ☀️☀️', 'Team Super Zay’in', 'Scary Terry’s Turbulators', NULL, NULL, 'STT -0.1', NULL, NULL, 'TSZ travel to Bank of America Stadium to take on the Turbulators from Charlotte. After a tough couple years, TSZ finally had some success by making the postseason last year. They’ll look to progress forward into a contender as many consider them the team with the highest ceiling in the league. Led by their star returning RB Bijan Robinson and their X factor in Devon Achane, the Super Zay’ins want to start their season off with a bang. After a miraculous playoff push which was ended on the final week by their rival, STT looks to get back on the saddle and make a championship run this season. Mr. Hong was caught reaching multiple times during the draft but he seems to have got his guys for 2024. They are led by star RBs in Pacheco and Walker, and all-pro WRs Wilson and McLaurin. The Turbulators will be the slight favorites, but this matchup is the closest projected game according to the book.'),
  ('94b9affa-b54d-448a-bd3b-0e90bc2dec24', '9ecc626c-04e6-4bf6-abd1-0ca1e1e4bf0f', 4, '4:25 (Fox)', 'Team Drako', 'Ladd’s Lads 🌇🌇', NULL, NULL, 'LL -2.7', NULL, NULL, 'Team Drako travels to Seattle to face Ladd’s Lads. After a captivating story of a season, starting 0-5 and then winning 8 out of their next 9, Team Drako looks to build off a top 4 finish last year into a championship campaign this year. They are led by their star RB Breece Hall and the highest scoring player in fantasy football last season Josh Allen. Ladd’s Lads had somewhat of an opposite season to Team Drako as they started off as the clear favorite, but over time they cooled off leading to a disappointing finish. The Lads have been a contender these past few years but never got over the hump of winning a championship. They’ll look to change their fortunes with star WR Tyreek Hill and a stack of Ravens in Lamar and Andrews. Ladd’s Lads are the home favorite and this matchup is projected to be the highest scoring game of the week.'),
  ('dceea176-7b80-4b35-948b-5ffca0fbea6d', '9ecc626c-04e6-4bf6-abd1-0ca1e1e4bf0f', 5, 'SNF (NBC) ⭐️⭐️', 'Chasing 0-1', 'Code Monkey (MASTER)', NULL, NULL, 'C01 -5.2', NULL, NULL, 'Chasing 0-1 travels to our country’s capital to take on longtime rival Code Monkey (MASTER) under the lights in this week’s Primetime game. Our defending champs are coming off a dominant season where everything worked perfectly. Even though they are considered the favorites against a joke of a team/owner, Mr. Nanugonda believes his team isn’t quite ready and they’ll start 0-1. This is a rather peculiar scenario but we should not question a champion. They are led by Ja’marr Chase and Travis Etienne. After being added as an expansion team in 2020, Code Monkey was believed to be a contender straight away and be a title holder by this season. Everything seemed to go by plan until Mr. Kodali’s team finished last place in 2022. Many, including myself, thought it was a fluke. But Code Monkey saw themselves lose 11 games in a row and finish last place again in 2023. After a tough offseason of self-doubt and harassment from others, Code Monkey knows that this season is their last chance to save their reputation. They’ll look to start with a statement win at home and continue beating their rival in Week 1. The defending champs are the five point favorites in this predicted low scoring game.'),
  ('6712381e-be1e-4e78-a745-f1696a395e79', '9ecc626c-04e6-4bf6-abd1-0ca1e1e4bf0f', 6, 'MNF (ESPN/ABC) 🌙🌙', 'Joe Mama 😈', 'Christian Crusaders', NULL, NULL, 'CC -3.1', NULL, NULL, 'Joe Mama travels to New York City to take on the newly relocated Christian Crusaders at MetLife Stadium. A somewhat mediocre season by Joe Mama’s standards brings new pressure to their ball club. After failing to reach the Final Four for the second consecutive year, Mr. Bobba made sure he got his guys throughout the draft and strayed away from the players he does not believe in. His team is led by Amon Ra and Joe Burrow. Last year marks the Crusaders’ eight consecutive year without a postseason appearance. Upon the fear of us asking Mr. Nangali the reason for his failures, he chose not to show up to his preseason interview (they’ll be out soon dw). This season they are led by the 1.01 Cmac and the best player in the NFL Patrick Mahomes. They’re projected first place by ESPN voters.  The Crusaders are the home favorite but many believe betting on Joe Mama is the shark play.')
ON CONFLICT (article_id, position) DO NOTHING;

