INSERT INTO article_matchups (id, article_id, position, slot_label, away_team_name, home_team_name, away_record, home_record, line, away_score, home_score, body)
VALUES
  ('71803c0f-52b7-4159-a903-3ad733533930', 'e9ce0e30-9c52-4dec-92d5-8a9913ae71be', 1, NULL, 'Code Monkey (Master)', 'Chasing an Identity', NULL, NULL, NULL, 119.88, 116.18, 'Fantasy Football turns friends into enemies, intelligent men into retards. So was the case in this infamous matchup between week 1 rivals Ankith and TJ. Team Code Monkey (Master) squeaks out a win against Team Chasing an Identity with a standout performance by his Chicago D/ST. A promising win for Team Code Monkey (Master) gives him some much needed momentum going into Week 2 as he aims to establish a presence in this league after back to back last place finishes. A troubling loss, but not an unexpected one for Team Chasing an Identity as historically this has been a nightmare Week 1 matchup for the franchise. A strong performance from Chris Godwin at the Flex put Team Chasing an Identity in a position to win but ultimately could not make up for the lackluster production from his studs. A loud presence in the league, look out for fireworks in the coming weeks should Team Chasing an Identity fall to 0-2.'),
  ('dc7c5f00-c904-4907-b982-3cdee7073a67', 'e9ce0e30-9c52-4dec-92d5-8a9913ae71be', 2, NULL, 'I Cook Brown Rice', 'Christian Crusaders', NULL, NULL, NULL, 121.66, 97.94, 'A definitive win by Team I Cook Brown Rice hands the Crusaders their first loss of the season. The Crusaders will seek reparations from Coach Kyle Shanahan as his game time decision cost the Crusaders their first win of the season. Despite a lack of production from St. Brown, sharp draft picks in Rashee Rice and Nico Collins coupled with a remarkable 26.6 points from Jake Moody put Team Brown Rice on top. A lack of skill positional depth means The Crusaders will be looking to Jesus these next few weeks as they hope for their star RB to return to playing form. Further worrisome is an ankle injury for TE David Njoku, leaving the Crusaders with the Mission of scouring the Waiver Wire for what is already a thin position (Tyler Conklin is not an option). If not, the gates of Heaven may be closing for this team early as they travel to DC for a tough matchup against the Code Monkey.'),
  ('812b6798-de9b-4852-9fa2-4d5c996d0269', 'e9ce0e30-9c52-4dec-92d5-8a9913ae71be', 3, NULL, 'Team Drako', 'Ladd’s Lads', NULL, NULL, NULL, 125.58, 114.32, 'Exceptional performances by fantasy GOAT Josh Allen, Mike Evans, and the tandem of Breece Hall and Aaron Jones give Team Drako a strong head start as the season begins. The tide may be turning for a historically underperforming franchise as a breakout performance from former first-round pick Jameson Williams gives promise to the future and a needed reprieve from having to start Javonte Williams. In line with new league initiatives, Team Drako has debuted an increasingly diverse roster, now only starting a total of 3 white players (which still ties for the league-high). He will look to build upon this in the coming weeks. The Lads will be looking to make some moves on the waiver wire and changes to their starting lineup as Raheem Mostert has been ruled out for Thursday’s matchup against the Bills. Rookie namesake Ladd McConkey showed out in his NFL debut, displaying a rapport with QB Justin Herbert that shows promise for the weeks to come. McConkey has yet to make his debut as a starter for his eponymous team but a poor performance by Amari Cooper means this GM may be looking to shake things up. These are both teams to watch as we continue to make our way through the season.'),
  ('cff4e1bd-fb81-43ad-97c1-119d5481e0ea', 'e9ce0e30-9c52-4dec-92d5-8a9913ae71be', 4, NULL, 'My Puka Bear', 'JJ Phoenix Rising', NULL, NULL, NULL, 143.06, 128.12, 'What a statement by the 3x champion franchise My Puka Bear as they put Team JJ Phoenix Rising to bed. The Puka Bears are ones to watch moving forward. Of note, team Puka Bear has lost their namesake starter to a knee injury, causing the standout sophomore WR to hit the IR slot. Team JJ Phoenix Rising put up a respectable performance, led by strong production by fantasy Kicker darling Brandon Aubrey. Despite the team-high 22.3 points garnered by Aubrey, JJ Phoenix Rising could not prevent the inevitable — a showstopping 143.06 point Pukkake with GM Kirk Broadbelt at its center.'),
  ('4805869c-bf0f-4515-af85-44df43152450', 'e9ce0e30-9c52-4dec-92d5-8a9913ae71be', 5, NULL, 'Super Zay’in', 'Scary Terry’s Turbulators', NULL, NULL, NULL, 84.76, 118.2, 'The anime-inspired team headed by GM Amogh Natu failed to channel their inner ‘super Saiyan’ in week 1 as they fell victim to a decisive 34 point beatdown by the Turbulators. Despite their strong week 1 performance, however, GM Joseph “No Hoes” Hong’s Turbulators are experiencing some turbulence of their own as a week 1 injury to starting QB Jordan Love means darker days may be ahead. Backup QB Caleb Williams is still looking to find his sea legs after an underwhelming week 1 performance that saw him record just 7.2 points. Better hope he finds them soon or things are going to get a lot scarier for the Turbulators as their ship begins taking on water. Perhaps controversially, Team Super Zay’in may be a team to pay attention to in the coming weeks as they look to produce a bounce-back performance against team Kupp Kupp and Away! In Week 2. A surprising wealth of depth at the Rb position puts this team in a stronger position moving forward than Players Poll rankings may imply. Nonetheless, faced with that strong week 2 matchup,  Team Super Zay’in will be looking for as much production as they can or they’ll quickly find themselves the “Baka” bowing down to their Senpai.'),
  ('889fc041-c958-4c45-91aa-66ddb3f80203', 'e9ce0e30-9c52-4dec-92d5-8a9913ae71be', 6, NULL, 'Kupp Kupp and Away!', 'London is Red', NULL, NULL, NULL, 144.78, 81.46, 'It appears to be a bloodbath in London as Team Kupp Kupp and Away comes up with the largest margin of victory amongst the week 1 slate. Things seemed to fall apart for GM Rishi “commish” Nookala’s team as they put up a measly 81.46 points. He would like to thank the Cleveland Browns for being a shit franchise and letting the Cowboys waltz all over them, thus allowing Dak and Ceedee to take the day off. He would also like to thank Kirk Cousins for being a fraud and Josh Allen for not looking out for his fellow white man Kincaid. Perhaps Kaepernick did cause some change. Surprisingly, Team London is Red has a bright Week 2 outlook with the emergence of Jordan Mason, giving the team the highest projected point total amongst the league in Week 2. The Nuke will look to capitalize on this projection as he faces a stout offense in Team Puka Bear in Week 2. On the other hand Kupp Kupp and Away! seems to be living up to his name, as an exceptional performance by WR Cooper Kupp gives promise to another year of competence for this decorated franchise.')
ON CONFLICT (article_id, position) DO NOTHING;

