INSERT INTO article_matchups (id, article_id, position, slot_label, away_team_name, home_team_name, away_record, home_record, line, away_score, home_score, body)
VALUES
  ('8bb4868a-989c-4f6a-b27b-7a20d31375e0', '7227a335-1f24-475b-9466-dbbbe897c75c', 1, 'Thursday Night Football 8:15 PM', 'Code Monkey (PR#414)', 'Tet Offensive', '2-1', '1-2', 'TO +6.92', NULL, NULL, 'After a tough loss to open the season vs bitter rival TJ, Ankith’s Code Monkey’s will look to continue their winning streak at Lambeau against Tet Offensive. It looks like Sparsh’s black magic has finally worn off, but I’m pretty sure I just jinxed it and will be receiving death threats by the end of the season. Anyway, TO rosters two great Tar Heels in Drake Maye and Omarion Hampton, both of which seem to be rising stars. Combined with his competent receiving corps, this team should be able to win games moving forward. However, it’ll be tough this week against one of the best teams in the league, and the spread reflects that.'),
  ('db14f5f5-d790-4f6b-a201-2c57bd0df66d', '7227a335-1f24-475b-9466-dbbbe897c75c', 2, 'NFL Dublin Game Sunday 9 AM', 'Jayden Jefferson Jr’s Mom', 'Ladd’s Ladds', '1-2', '1-2', 'LL +8.88', NULL, NULL, 'On the heels of their first win of the season, JJJM returns to the motherland to face Keshav’s Ladds, who are coming off a close loss to Code Monkey. After finally showcasing their offensive potential, albeit in an unexpected way, Carter will be hoping that his team can get the luck of the Irish and produce their most balanced output of the season at Croke Park. Meanwhile, the Ladds have had a rough start to the season but still have the reigning league MVP, who has shown he is capable of putting up historic fantasy numbers. This one won’t exactly be worth waking up for, but if watching football cures your hangover than you might want to tune in.'),
  ('2a1a1042-10b7-4aac-8672-9b17b3fc4693', '7227a335-1f24-475b-9466-dbbbe897c75c', 3, '1 PM Kickoff', 'Bill👍', 'Nangali’s Naners', '0-3', '1-2', 'Bill👍 +13.14', NULL, NULL, 'Bill👍 has struggled somewhat unexpectedly to start the season, as Revanth typically fields strong teams year in and year out. His playoff chances took another severe hit with due to his best player sustaining a high ankle sprain. The team will look to stay alive at WakeMed Soccer Park in Cary against Nangali’s Naners, who just made their first trade in years and are better than their record reflects. Sam’s well rounded squad, which features one of the best collection of skill players in the league, will look to exploit Rev’s lack of quality RBs and even their record on the season.'),
  ('296818fd-aa8a-4d59-b8d6-4e2eff221258', '7227a335-1f24-475b-9466-dbbbe897c75c', 4, '4:25 PM Kickoff', 'Trisomy 21', 'Stevenson and White Guys For', '2-1', '0-3', 'SWGF +6.01', NULL, NULL, 'America’s game of the week (kind of) takes us over to (not so) beautiful Carter-Finley Stadium in Raleigh. Outspoken manager TJ, coming off his worst performance of the season, puts his team on display against Alvin’s struggling white guys. We will see how this one plays out, as weather may play a factor in limiting star wideout Malik Nabers once again. The white guys will try to prove the typical stereotypes wrong by getting their first win of the season in what would be a major upset on the road. Rookie RB Ashton Jeanty will need to finally break out for them to have a shot against T21’s high powered offense.'),
  ('4fad47e6-0103-4f0d-aa77-8b6b98be88b0', '7227a335-1f24-475b-9466-dbbbe897c75c', 5, 'Sunday Night Football 8:20 PM', 'Heterophobes Reloaded😈', 'Kamara vs the World', '3-0', '3-0', 'HR +3.95', NULL, NULL, 'An early season blockbuster matchup awaits on Sunday Night at BOA Stadium in Charlotte. Joseph’s team has taken a major leap and is now arguably the frontrunner to win it all with its lethal combination of LJ and Bijan that provides a comfortable floor of well over 40 points per week. However, defending champion Amogh is slightly favored to win this one behind a QB who is playing at a career level, an elite receiver and breakout star Rome Odunze. Look forward to plenty of fireworks when the two best teams in the league clash to wrap up another great day of football.'),
  ('6cf57013-8f2b-4030-bda8-3bd6084473fd', '7227a335-1f24-475b-9466-dbbbe897c75c', 6, 'Monday Night Football 8:15 PM', 'It Hurts a Little', 'Bark for Daddy!', '2-1', '2-1', 'Hurts +2.58', NULL, NULL, 'Our third and final game in the Triangle will be held in primetime at Middle Creek High School. It Hurts a Little is actually the slight underdog in this matchup despite possessing what most believe to be the better roster. The commissioner is coming off a huge win against the “Naners and has an abundant of talent at running back but no true #1 receiver. On the flip side, Kirk will look to bounce back and get much more from star RB Saquon Barkley after an embarrassing loss last week (at least the only other Caucasian was the top scorer) in this matchup of two solid teams to close out the week.')
ON CONFLICT (article_id, position) DO NOTHING;

