VALUES ('91a8c7dc-2f2e-49ba-96cc-54ec0e375030', 2025, 8, 'preview', '2025/week-eight-preview', '2025 Week 8 Preview', 'We are almost at the midpoint of the nfl season. See what''s going on in the Cary Bengals Fantasy Football league', NULL, NULL, 'published', '2025-10-23', NULL, 'ankith')
