VALUES ('013d3688-347b-4da2-91f1-e63bc8ffddbb', 2025, 9, 'preview', '2025/week-nine-preview', '2025 Week 9 Preview', 'Get ready for another exciting week of football with the Cary Bengals!', NULL, NULL, 'published', '2025-10-31', NULL, 'kirk')
