INSERT INTO articles (id, season_year, week_number, kind, slug, title, summary, intro_markdown, outro_markdown, status, published_at, author_id, author_slug)
VALUES ('b0fe6439-34b7-4b02-b968-f0cc12b5a90b', 2025, 10, 'preview', '2025/week-ten-preview', '2025 Week 10 Preview', 'Playoffs are around the corner! Read about what teams are fighting for playoff contention, and who is fighting not to get last', NULL, NULL, 'published', '2025-11-06', NULL, 'joseph')
