INSERT INTO article_matchups (id, article_id, position, slot_label, away_team_name, home_team_name, away_record, home_record, line, away_score, home_score, body)
VALUES
  ('7e4ef57f-105a-4ed0-ae30-725bc8bab6e6', 'b0fe6439-34b7-4b02-b968-f0cc12b5a90b', 1, 'Thursday Night Football', 'Nangali’s Naners', 'Indian DJ', NULL, NULL, NULL, NULL, NULL, 'This has been a pretty disappointing season for the Naners who were arguably the preseason favorite. On paper, they probably are the best team from top to bottom. However, a lack of moves by Sam has put this team at 3-6 and amidst a 4 game losing streak. Honestly, their fans and league members are confused as to how this team is not in the top half of the league. Which super team is worse: The Naners or the 12-13 a Lakers? They will hope to get back to winning ways when they face off against Indian DJ back in Downtown Raleigh. TJ’s squad has been underwhelming this season as well. He is coming off a heartbreaker where he was once projected over 70% chance to win. Week 10 will be a crucial matchup for both teams who are looking to turn a corner in the 2nd half of the season.'),
  ('95916122-13e6-4bea-83ec-e8f4d23521e7', 'b0fe6439-34b7-4b02-b968-f0cc12b5a90b', 2, 'NFL International Game (Berlin)', 'Bark for Daddy!', 'Jayden Jefferson Jr’s Mom', NULL, NULL, NULL, NULL, NULL, 'Hallo, Deutschland! Nothing is more suiting than this historic and great Whiteout Rivalry game taking place in Berlin, Germany- a place known for its deep history and attempt at “whitingout” in the 1900s 🫡. Bark for Daddy has been decimated due to bye week trouble and will have to start some questionable players to fill in those gaps. You could say his players are “gassed” out and need a break. Still, Kirk boasts a 6-3 record and sits tied for 2nd and will try to silence the haters who placed him in the bottom half in the Manager Poll. Carter has finally made a trade and is now rocking the 3 RB strategy this week. However, he did lose star Jayden Daniels, who most likely will be out for the rest of the fantasy regular season. Carter comes into this matchup as a heavy favorite and will look to cement his superiority this week.'),
  ('bbed38ed-af5c-401a-b26b-7ac51b29910a', 'b0fe6439-34b7-4b02-b968-f0cc12b5a90b', 3, 'Fox 1 pm', 'Code Monkey (PR #414)', 'Kamara vs the World', NULL, NULL, NULL, NULL, NULL, 'Big matchup this week as number one Team Code Monkeys takes the drive to Purdue to face Kamara vs the World. Ankith made a mid-week trade to acquire a top QB in Jaxson Dart, which firmly puts his team in serious contention to win the entire thing. While other teams are struggling with injuries and byes, this team has no byes and only 1 minor injury to worry about. On the other hand, Amogh has several key players out including Terry “Ben Simmons” Mclaurin. The inevitable first-place poll curse has hit Amogh hard and he is now in a 3 game skid. He will hope that his stud Puka Nacua is back to full health and delivers an all timer. Ankith is the betting favorite and will try to walk into Amogh’s trap and take over his trap (something GT couldn’t do)'),
  ('992cf688-e812-4dca-be1f-a0dceb3f464c', 'b0fe6439-34b7-4b02-b968-f0cc12b5a90b', 4, 'CBS 4:25pm', 'Stevenson and White Guys For', 'Heterophobes Locked In', NULL, NULL, NULL, NULL, NULL, 'The battle of the East will ironically take place in the East (of the US). Stevenson and White Guys for take the red eye to Charlotte to face the Heterophobes. As of late, Alvin’s squad has been disrespected and put in last place in manager polls. However, they got a key win last week to provide some hope in a playoff push and honestly not finishing in last. Jeanty is coming to form, and elite WR Garrett Wilson should be returning from injury. The Heterophobes faced some heavy turbulence these last 5 weeks but were finally able to snap the losing streak. Joseph came out with a close win thanks to the glorious Brock Bowers who left their manager, Brock hard after dropping 43 points. They will look to continue this momentum and sneak into the playoffs - (as long as some dumb mf doesn’t muff a punt block).'),
  ('59e812c4-4e46-46ff-9402-7e06867bdfaa', 'b0fe6439-34b7-4b02-b968-f0cc12b5a90b', 5, 'Primetime SNF NBC', 'Tet Offensive', 'It Hurts a Little', NULL, NULL, NULL, NULL, NULL, 'Everyone knew it was coming. Sparsh’s devil magic lives on. After starting off 1-4 and looking like a lock to miss playoffs, this team has rattled off 4 straight wins and now sit inside the playoff picture. Is it ironic that he wins after he sacrificed Hampton? Yes, but that is how this manager rolls. What type of sacrifices and rituals happen in his room, we will never know. Rishi’s squad is sitting in 2nd place and is still one of the favorites in the league. Although there are allegations of racism in this league and protestors are crying, the commissioner has held firm and stated , “Racism is tolerated”. He hopes to create some buffer for his squad by going from 6 to 7 wins 😈.'),
  ('c2f76ccf-e8ad-4bf0-a442-617877be96f1', 'b0fe6439-34b7-4b02-b968-f0cc12b5a90b', 6, 'MNF ESPN', 'Free Thugger', 'Maye I Digg in yo Boutte', NULL, NULL, NULL, NULL, NULL, 'Free Thugger has also sold his soul to the devil and somehow have all his handcuff rbs emerge to RB1 level. He has turned into prime Jack the Ripper in the streets of Seattle and in turn has an above .500 record. Keshav has remained level-headed when there were calls to trade away his studs earlier in the season and now sees the benefits from that decision. Revanth on the other hand suffered a heartbreaking loss last week that put him back into sole last place in the league. He also has Ceedee Lamb on bye this week, which puts him at a further disadvantage. One of these former roommates and secret lovers will hope to “come out on top” (Ayo) in this rivalry game.')
